#!/usr/bin/env bash
#
# First deploy of gabrieldiem.com to Portainer. Run once from the repo root, before merging the
# branch that turns the deploy on: deploy/first-deploy-wizard.sh
# Safe to re-run: it finds the stack if it already exists. A wizard walks a human through a manual
# procedure, step by step. Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the steps only Gabriel can do, because they need his credentials.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

PORTAINER_URL=${PORTAINER_URL:-https://portainer.gabrieldiem.com}
REGISTRY_URL=${REGISTRY_URL:-https://registry.gabrieldiem.com}
SITE_URL=${SITE_URL:-https://gabrieldiem.com}
REPO=gabrieldiem/gabrieldiem.com
REGISTRY_HOST=registry.gabrieldiem.com
IMAGE="$REGISTRY_HOST/gabrieldiem-com-web"
STACK_NAME=gabrieldiem-com
GH_ENV=prod
GYMBROS_ENDPOINT=1
EDGE_SSH=${EDGE_SSH:-awsbr_edge_gabriel}
TITLE='<title>Gabriel Diem</title>'

die() {
  warn "$1"
  note "Nothing is broken. Fix that and run this wizard again: it picks up where it can."
  exit 1
}

# Calls Portainer with the key in a curl config on a file descriptor, so it never appears in `ps`.
portainer() {
  curl -sS --max-time 180 --config <(printf 'header = "X-API-Key: %s"\n' "$PORTAINER_API_KEY") "$@"
}

# The template's set_secret and set_var write repo-level values. CI reads these from the prod
# environment, the same as GYMBROS.
set_env_secret() {
  printf '%s' "$2" | gh secret set "$1" --env "$GH_ENV" --repo "$REPO" >/dev/null ||
    die "Couldn't set the GitHub secret $1."
  WRITTEN_SECRET+=("$1")
  printf '  %s✓ set%s GitHub secret %s (%s)\n' "$GREEN" "$RESET" "$1" "$GH_ENV"
}
set_env_var() {
  gh variable set "$1" --env "$GH_ENV" --repo "$REPO" --body "$2" >/dev/null ||
    die "Couldn't set the GitHub variable $1."
  printf '  %s✓ set%s GitHub variable %s=%s (%s)\n' "$GREEN" "$RESET" "$1" "$2" "$GH_ENV"
}

# Removes the throwaway Docker config that holds the registry password.
forget_login() {
  rm -f "$DOCKER_LOGIN_DIR/config.json"
  rmdir "$DOCKER_LOGIN_DIR" 2>/dev/null || true
}

# Runs on the edge over SSH. Appends the site, validates, reloads, and puts the old file back if the
# new one doesn't validate, so the other sites on this Caddy keep running.
caddy_setup_script() {
  cat <<'REMOTE'
set -eu
CADDYFILE=/etc/caddy/Caddyfile
if grep -q '^gabrieldiem\.com {' "$CADDYFILE"; then
  echo "The site is already in the Caddyfile."
  exit 0
fi
BACKUP="$CADDYFILE.bak.$(date +%Y%m%d%H%M%S)"
sudo cp -p "$CADDYFILE" "$BACKUP"
sudo tee -a "$CADDYFILE" >/dev/null <<'SITE'

# gabrieldiem.com → Portainer stack web (127.0.0.1:8091).
gabrieldiem.com {
	reverse_proxy 127.0.0.1:8091
}

www.gabrieldiem.com {
	redir https://gabrieldiem.com{uri} permanent
}
SITE
if ! sudo caddy validate --adapter caddyfile --config "$CADDYFILE" >/dev/null 2>&1; then
  sudo cp -p "$BACKUP" "$CADDYFILE"
  echo "The new Caddyfile didn't validate, so the old one is back and Caddy wasn't reloaded."
  exit 1
fi
sudo systemctl reload caddy
echo "Caddy reloaded. Backup: $BACKUP"
REMOTE
}

run_wizard() {

TOTAL_STAGES=8

banner "First deploy of gabrieldiem.com to Portainer"

stage "Check this machine"
for tool in gh docker curl jq git; do
  command -v "$tool" >/dev/null 2>&1 || die "$tool is not installed."
done
gh auth status >/dev/null 2>&1 || die "gh is not logged in. Run: gh auth login"
docker info >/dev/null 2>&1 || die "Docker is not running."
[[ -f deploy/compose.edge.yaml ]] || die "Run this from the root of the repo."
SHA=$(git rev-parse HEAD)
say "This wizard builds and deploys the commit you have checked out: ${SHA:0:7}"
if [[ -n "$(git status --porcelain)" ]]; then
  warn "You have uncommitted changes, and they will go into the image."
fi
pause "Press Enter to continue"

stage "Portainer access"
say "CI deploys with a Portainer access token. Use the same user as GYMBROS, ci, so it owns this"
say "stack and can update it. If you still have the GYMBROS token, you can reuse it."
open_url "$PORTAINER_URL"
step "Log in as ci, then open your user menu → My account → Access tokens → Add access token."
step "Name it gabrieldiem-com-ci and copy the token."
ask_secret PORTAINER_API_KEY "Paste the Portainer access token:"
endpoints=$(portainer --fail "$PORTAINER_URL/api/endpoints") ||
  die "Portainer rejected that token."
printf '\n'
say "Environments this token can reach:"
jq -r '.[] | "    \(.Id)  \(.Name)"' <<<"$endpoints"
printf '\n'
note "GYMBROS deploys to environment $GYMBROS_ENDPOINT. Pick another if the site belongs elsewhere."
ask PORTAINER_ENDPOINT_ID "Environment ID [Enter for $GYMBROS_ENDPOINT]:"
PORTAINER_ENDPOINT_ID=${PORTAINER_ENDPOINT_ID:-$GYMBROS_ENDPOINT}
jq -e --argjson id "$PORTAINER_ENDPOINT_ID" 'any(.[]; .Id == $id)' <<<"$endpoints" >/dev/null ||
  die "There's no environment with ID $PORTAINER_ENDPOINT_ID."
pause "Press Enter to continue"

stage "Registry access"
say "CI pushes images to the private registry as the ci user. It's the password GYMBROS uses for"
say "REGISTRY_CI_PASSWORD. GitHub won't show it again, so it comes from your password manager."
ask_secret REGISTRY_CI_PASSWORD "Paste the registry password for ci:"
code=$(curl -s --max-time 20 -o /dev/null -w '%{http_code}' \
  --config <(printf 'user = "ci:%s"\n' "$REGISTRY_CI_PASSWORD") "$REGISTRY_URL/v2/") || code=000
[[ "$code" == 200 ]] || die "The registry answered $code for that password."
printf '  %s✓ the registry accepts it%s\n' "$GREEN" "$RESET"
pause "Press Enter to continue"

stage "Configure GitHub"
say "Creates the $GH_ENV environment on $REPO and stores what the Deploy workflow needs."
gh api --silent -X PUT "repos/$REPO/environments/$GH_ENV" ||
  die "Couldn't create the $GH_ENV environment."
printf '  %s✓ environment%s %s\n' "$GREEN" "$RESET" "$GH_ENV"
set_env_secret PORTAINER_API_KEY "$PORTAINER_API_KEY"
set_env_secret REGISTRY_CI_PASSWORD "$REGISTRY_CI_PASSWORD"
set_env_var PORTAINER_URL "$PORTAINER_URL"
set_env_var PORTAINER_ENDPOINT_ID "$PORTAINER_ENDPOINT_ID"
pause "Press Enter to continue"

stage "Build and push the first image"
say "A Portainer stack needs an image that already exists, so the first one is built here."
say "Every image after this one comes from CI."
printf '\n'
docker build -t "$IMAGE:$SHA" apps/web || die "The image didn't build."
# A throwaway Docker config, so the registry password isn't left in ~/.docker/config.json.
DOCKER_LOGIN_DIR=$(mktemp -d)
printf '%s' "$REGISTRY_CI_PASSWORD" |
  DOCKER_CONFIG=$DOCKER_LOGIN_DIR docker login "$REGISTRY_HOST" -u ci --password-stdin >/dev/null ||
  { forget_login; die "Docker couldn't log in to the registry."; }
DOCKER_CONFIG=$DOCKER_LOGIN_DIR docker push "$IMAGE:$SHA" ||
  { forget_login; die "The push failed."; }
forget_login
printf '  %s✓ pushed%s %s:%s\n' "$GREEN" "$RESET" "$IMAGE" "${SHA:0:7}"
pause "Press Enter to continue"

stage "Create the Portainer stack"
stacks=$(portainer --fail "$PORTAINER_URL/api/stacks") || die "Couldn't list the Portainer stacks."
PORTAINER_STACK_ID=$(jq -r --arg name "$STACK_NAME" '[.[] | select(.Name == $name) | .Id][0] // empty' <<<"$stacks")
if [[ -n "$PORTAINER_STACK_ID" ]]; then
  say "Stack $STACK_NAME already exists, with ID $PORTAINER_STACK_ID, so it stays as it is."
else
  taken=$(portainer --fail "$PORTAINER_URL/api/endpoints/$PORTAINER_ENDPOINT_ID/docker/containers/json" |
    jq -r '[.[] | select(any(.Ports[]?; .PublicPort == 8091)) | .Names[0]] | join(", ")') ||
    die "Couldn't read the containers in environment $PORTAINER_ENDPOINT_ID."
  [[ -z "$taken" ]] || die "Port 8091 is already used by: $taken. Change it in deploy/compose.edge.yaml."
  say "This starts the site's container in environment $PORTAINER_ENDPOINT_ID, on 127.0.0.1:8091."
  say "No other stack is touched."
  confirm "Create stack $STACK_NAME on ${SHA:0:7}?" || die "Stack not created."
  payload=$(jq -n --arg name "$STACK_NAME" --rawfile file deploy/compose.edge.yaml --arg tag "$SHA" \
    '{Name: $name, StackFileContent: $file, Env: [{name: "IMAGE_TAG", value: $tag}]}')
  created=$(portainer --fail-with-body -X POST -H 'Content-Type: application/json' --data-binary @- \
    "$PORTAINER_URL/api/stacks/create/standalone/string?endpointId=$PORTAINER_ENDPOINT_ID" <<<"$payload") ||
    die "Portainer couldn't create the stack: $created"
  PORTAINER_STACK_ID=$(jq -r '.Id' <<<"$created")
  printf '  %s✓ created%s stack %s\n' "$GREEN" "$RESET" "$PORTAINER_STACK_ID"
fi
set_env_var PORTAINER_STACK_ID "$PORTAINER_STACK_ID"
say "Waiting for the container to be healthy..."
for attempt in $(seq 1 24); do
  status=$(portainer --fail "$PORTAINER_URL/api/endpoints/$PORTAINER_ENDPOINT_ID/docker/containers/json?all=1" |
    jq -r --arg p "$STACK_NAME" '[.[] | select(.Labels["com.docker.compose.project"] == $p) | .Status][0] // "not started"') ||
    status="unknown"
  [[ "$status" == *"(healthy)"* ]] && break
  [[ "$attempt" -lt 24 ]] && sleep "${POLL_SECONDS:-5}"
done
[[ "$status" == *"(healthy)"* ]] || die "The container isn't healthy: $status. Check it in Portainer."
printf '  %s✓ container healthy%s\n' "$GREEN" "$RESET"
pause "Press Enter to continue"

stage "Point Caddy at it"
say "gabrieldiem.com already resolves to the edge, but Caddy has no site for it yet. This adds it to"
say "/etc/caddy/Caddyfile over SSH ($EDGE_SSH), keeps a backup, validates the file and reloads Caddy."
say "A reload keeps the other sites running. Your sudo password is typed into the SSH session."
printf '\n'
if confirm "Update Caddy on the edge?"; then
  ssh -t "$EDGE_SSH" "$(caddy_setup_script)" || die "Caddy wasn't updated."
else
  die "Caddy not updated, so the site can't go live yet."
fi
pause "Press Enter to continue"

stage "Check the live site"
say "The first request also gets the HTTPS certificate, which can take a minute."
while true; do
  if curl -fsS --max-time 20 "$SITE_URL/" 2>/dev/null | grep -qF "$TITLE"; then
    printf '  %s✓ %s is live%s\n' "$GREEN" "$SITE_URL" "$RESET"
    break
  fi
  warn "$SITE_URL isn't serving the site yet."
  confirm "Check again?" || break
done
pause "Press Enter to finish"

finish
say "Next: merge the deploy branch. Every push to master then tests, builds, scans, smoke-tests and"
say "deploys, and rolls back by itself if the live check fails."
say "Revoke any token you made and didn't use, in Portainer → My account → Access tokens."
printf '\n'
}

run_wizard "$@"; exit
